use serde::Serialize;use super::ConnectorFailure;use crate::services::import_v2::url_policy::UrlPolicy;
#[derive(Debug,Serialize)]#[serde(rename_all="camelCase")]pub struct XPost{pub id:String,pub author:String,pub published_at:String,pub text:String,pub media:Vec<String>}
#[derive(Debug,Serialize)]#[serde(rename_all="camelCase")]pub struct XDocument{pub public_url:String,pub posts:Vec<XPost>}
pub fn extract_json(json:&str,url:&str,release_enabled:bool)->Result<XDocument,ConnectorFailure>{if !release_enabled{return Err(ConnectorFailure::StructureChanged)}let v:serde_json::Value=serde_json::from_str(json).map_err(|_|ConnectorFailure::StructureChanged)?;if v["loginRequired"].as_bool()==Some(true){return Err(ConnectorFailure::LoginRequired)}let author=v["targetAuthor"].as_str().ok_or(ConnectorFailure::StructureChanged)?;let posts=v["posts"].as_array().ok_or(ConnectorFailure::StructureChanged)?.iter().filter(|p|p["author"].as_str()==Some(author)&&p["relationship"].as_str()!=Some("reply")).take(12).map(|p|XPost{id:p["id"].as_str().unwrap_or("").into(),author:author.into(),published_at:p["date"].as_str().unwrap_or("").into(),text:p["text"].as_str().unwrap_or("").into(),media:p["media"].as_array().into_iter().flatten().filter_map(|m|m.as_str()).filter_map(|u|UrlPolicy.normalize_for_session(u).ok()).map(|t|t.public.public_url).collect()}).collect();let target=UrlPolicy.normalize_for_session(url).map_err(|_|ConnectorFailure::StructureChanged)?;Ok(XDocument{public_url:target.public.public_url,posts})}
